// app/Providers/PaymentServiceProvider.php
class PaymentServiceProvider extends ServiceProvider
{
    public function register(): void
    {
        $this->app->singleton(PaymentGateway::class, function ($app) {      // stateless, expensive client: singleton is right
            return match (config('services.payment.driver')) {
                'bkash'  => new BkashGateway(config('services.bkash')),
                'stripe' => new StripeGateway(config('services.stripe')),
            };
        });
        $this->app->scoped(Cart::class, fn ($app) => Cart::forUser($app['request']->user()));   // per request
    }

    public function boot(): void
    {
        Model::preventLazyLoading(!$this->app->isProduction());
        Gate::policy(Order::class, OrderPolicy::class);
    }
}

// The consumer never knows which gateway exists
