// app/Contracts/SmsSender.php
interface SmsSender { public function send(string $to, string $body): void; }

// app/Services/LogSmsSender.php
class LogSmsSender implements SmsSender { public function send(string $to, string $body): void { Log::info("SMS to $to: $body"); } }

// app/Services/FakeSmsSender.php
class FakeSmsSender implements SmsSender { public array $sent = []; public function send(string $to, string $body): void { $this->sent[] = compact('to','body'); } }

// app/Providers/AppServiceProvider.php register()
$this->app->singleton(SmsSender::class, fn () => match (config('services.sms.driver', 'log')) {
    'log' => new LogSmsSender(),
    'fake' => new FakeSmsSender(),
});

// app/Console/Commands/SmsTest.php
class SmsTest extends Command {
    protected $signature = 'sms:test {to}';
    public function handle(SmsSender $sms): int { $sms->send($this->argument('to'), 'hello'); return self::SUCCESS; }
}

// tests/Feature/SmsTestCommandTest.php
public function test_it_sends_one_sms(): void {
    $fake = new FakeSmsSender();
    $this->app->instance(SmsSender::class, $fake);
    $this->artisan('sms:test', ['to' => '01700000000'])->assertSuccessful();
    $this->assertCount(1, $fake->sent);
    $this->assertSame('01700000000', $fake->sent[0]['to']);
}

// Under PHP-FPM every request is a fresh process, so 'singleton' effectively means 'per request'. Under Octane the
// worker process lives across requests, so the singleton built for request 1 is reused for request 2.

$this->app->scoped(CurrentTenant::class, fn ($app) => CurrentTenant::fromRequest($app['request']));
// scoped() = singleton within a request, flushed between requests by Octane and by queue workers.

// Rule: anything derived from the request or the authenticated user is scoped, never singleton.

$this->app->when(InvoiceExporter::class)
    ->needs(Filesystem::class)
    ->give(fn () => Storage::disk('invoices'));

$this->app->when(AuditExporter::class)
    ->needs(Filesystem::class)
    ->give(fn () => Storage::disk('audit'));

// Both classes depend on the same CONTRACT (a filesystem); only the instance differs by consumer.
// Two interfaces would duplicate the contract and force every future consumer to choose one — contextual binding keeps
// one contract and moves the decision to configuration.
